query TeamStat($id: Int!, $limit: Int!, $offset: Int!) {
  alias(id: $id) {
    id
    pastTeams: players(current: false, active: null, limit: $limit, offset: $offset) {
      id
      ...EightBallTeam
      ...NineBallTeam
      ...MastersTeam
      __typename
    }
    currentTeams: players(current: true, active: null) {
      id
      ...EightBallTeam
      ...NineBallTeam
      ...MastersTeam
      __typename
    }
    __typename
  }
}

fragment NineBallTeam on NineBallPlayer {
  id
  isActive
  role
  rosterPosition
  nickName
  matchesPlayed
  matchesWon
  session {
    id
    name
    __typename
  }
  skillLevel
  rank
  team {
    id
    name
    division {
      id
      isTournament
      __typename
    }
    __typename
  }
  __typename
}

